<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
class AdministracionMedicacion extends ModeloOperativo { protected $table='administraciones_medicacion'; protected $primaryKey='cod_administracion'; protected function casts(): array{return ['fecha_hora_programada'=>'datetime','fecha_hora_administracion'=>'datetime'];} protected static function booted(): void{static::saving(function(self $registro): void{if(! Prescripcion::query()->whereKey($registro->cod_prescripcion)->where('cod_residente',$registro->cod_residente)->exists()){throw \Illuminate\Validation\ValidationException::withMessages(['cod_prescripcion'=>'La prescripción no corresponde al residente.']);}});} public function prescripcion(): BelongsTo{return $this->belongsTo(Prescripcion::class,'cod_prescripcion','cod_prescripcion');} public function residente(): BelongsTo{return $this->belongsTo(Residente::class,'cod_residente','cod_residente');} }
